class Solution:
    def minCost(self, arr: List[int], brr: List[int], k: int) -> int:
        base = sum(abs(a - b) for a, b in zip(arr, brr))
        alt = k + sum(abs(a - b) for a, b in zip(sorted(arr), sorted(brr)))
        return min(base, alt)

