class Solution {
public:
    long long minCost(vector<int>& arr, vector<int>& brr, long long k) {
        long long base = 0;
        for (size_t i = 0; i < arr.size(); i++) base += llabs(arr[i] - brr[i]);
        vector<long long> a(arr.begin(), arr.end()), b(brr.begin(), brr.end());
        sort(a.begin(), a.end()); sort(b.begin(), b.end());
        long long alt = k;
        for (size_t i = 0; i < a.size(); i++) alt += llabs(a[i] - b[i]);
        return min(base, alt);
    }
};

