class Solution {
    public long minCost(int[] arr, int[] brr, long k) {
        long base = 0;
        for (int i = 0; i < arr.length; i++) base += Math.abs(arr[i] - brr[i]);
        long[] a = new long[arr.length], b = new long[arr.length];
        for (int i = 0; i < arr.length; i++) { a[i] = arr[i]; b[i] = brr[i]; }
        java.util.Arrays.sort(a); java.util.Arrays.sort(b);
        long alt = k;
        for (int i = 0; i < a.length; i++) alt += Math.abs(a[i] - b[i]);
        return Math.min(base, alt);
    }
}

