var minCost = function(arr, brr, k) {
    let base = 0;
    for (let i = 0; i < arr.length; i++) base += Math.abs(arr[i] - brr[i]);
    const a = [...arr].sort((x, y) => x - y), b = [...brr].sort((x, y) => x - y);
    let alt = k;
    for (let i = 0; i < a.length; i++) alt += Math.abs(a[i] - b[i]);
    return Math.min(base, alt);
};
